import http.server as h, functools as f
class H(h.SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store')
        super().end_headers()
h.ThreadingHTTPServer(('127.0.0.1', 5180), f.partial(H, directory='electron-app')).serve_forever()
